/// Look up a seed by its upstream id.
pub fn seed(id: u8) -> Option<&'static ExpressionSeed> {
    SEEDS.iter().find(|seed| seed.id == id)
}

/// Look up an eye-ring set by its upstream index.
pub fn rings(index: u8) -> Option<&'static EyeRings> {
    RINGS.get(index as usize)
}
